&lt;p&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Calibri,sans-serif&quot;&gt;&lt;span style=&quot;font-family:&amp;quot;Times New Roman&amp;quot;,serif&quot;&gt;Elimde beyaz bastonum&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

